reference_solution:
def reverse_words(s):
    words = []
    end = len(s) - 1
    while end >= 0:
        while end >= 0 and s[end] == " ":
            end -= 1
        if end < 0:
            break
        start = end
        while start >= 0 and s[start] != " ":
            start -= 1
        words.append(s[start + 1:end + 1])
        end = start - 1
    return " ".join(words)

